template <typename UnionPtrType>
GetOAuthAccessTokenResultPtr GetOAuthAccessTokenResult::Clone() const {
  switch (tag_) {
    case Tag::kNone:
      return NewNone(
          mojo::Clone(*data_.none));
    case Tag::kError:
      return NewError(
          mojo::Clone(*data_.error));
    case Tag::kToken:
      return NewToken(
          mojo::Clone(*data_.token));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, GetOAuthAccessTokenResult>::value>::type*>
bool GetOAuthAccessTokenResult::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kNone:
      return mojo::Equals(*(data_.none), *(other.data_.none));
    case Tag::kError:
      return mojo::Equals(*(data_.error), *(other.data_.error));
    case Tag::kToken:
      return mojo::Equals(*(data_.token), *(other.data_.token));
  }

  return false;
}
